// One item per web search. "X-ray" queries ask the search engine (not
// LinkedIn) for public profile and company pages, plus the employer's own
// pages and specialist agencies.
const { job = {}, candidate = {} } = $json.body ?? {};
const company = (job.company || '').trim();
const title = (job.title || '').trim();
const place = (job.location || job.country || '').trim();
const field = (candidate.targetRoles?.[0] || title).trim();
const q = [];
if (company) {
  q.push(`site:linkedin.com/in "${company}" (recruiter OR "talent acquisition" OR "recruitment partner")`);
  if (title) q.push(`site:linkedin.com/in "${company}" "${title}" (manager OR lead OR head)`);
  q.push(`"${company}" careers recruitment team contact`);
}
q.push(`recruitment agency "${field}" ${place}`.trim());
return q.map((query) => ({ json: { q: query } }));

// Collects the search results and asks Claude to pick the people worth
// contacting and say how to approach each. Only results the search
// returned may be cited, so nothing is invented.
const req = $('Webhook').first().json.body ?? {};
const seen = new Set();
const results = $input.all()
  .flatMap((i) => i.json.web?.results ?? [])
  .map((r) => ({ title: r.title, url: r.url, snippet: r.description }))
  .filter((r) => r.url && !seen.has(r.url) && seen.add(r.url))
  .slice(0, 40);
const text = (d) => ({ type: 'string', description: d });
const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['leads'],
  properties: {
    leads: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['name', 'title', 'company', 'kind', 'linkedin', 'email', 'source', 'why', 'approach'],
        properties: {
          name: text('A person, or a team such as "Recruitment team"'),
          title: text(''),
          company: text(''),
          kind: { type: 'string', enum: ['recruiter', 'hiring_manager', 'referral', 'peer', 'mentor', 'other'] },
          linkedin: text("A linkedin.com URL copied exactly from the results, or ''"),
          email: text("Only an address published for job enquiries in the results, or ''"),
          source: text('The result URL this came from'),
          why: text('Why this person or team matters for this job'),
          approach: text('How to approach them, with a connection note under 300 characters'),
        },
      },
    },
  },
};
return [{
  json: {
    results,
    body: {
      model: 'claude-opus-5-5',
      max_tokens: 8000,
      system:
        'You help a job seeker find the right people to contact about one job. Use only the search ' +
        'results given; never invent people, URLs or e-mail addresses, and leave out private contact ' +
        'details. Prefer, in order: the named recruiter or hiring manager, the employer\'s recruitment ' +
        'team, specialist agencies for this field and area, and peers in the same team. At most 10.',
      messages: [{
        role: 'user',
        content: JSON.stringify({ job: req.job, candidate: req.candidate, searchResults: results }),
      }],
      output_config: { effort: 'medium', format: { type: 'json_schema', schema } },
    },
  },
}];

// Claude's answer as {"leads": [...]} for Udyoga. Links that were not in
// the search results are dropped.
const reply = $input.first().json;
const allowed = new Set($('Prepare Claude request').first().json.results.map((r) => r.url));
let data = { leads: [] };
try {
  data = JSON.parse((reply.content ?? []).filter((b) => b.type === 'text').map((b) => b.text).join(''));
} catch (e) {
  // Answered in an unexpected form: return no leads rather than fail.
}
const leads = (data.leads ?? []).map((l) => ({
  ...l,
  linkedin: allowed.has(l.linkedin) ? l.linkedin : '',
  source: allowed.has(l.source) ? l.source : '',
}));
return [{ json: { leads } }];
